import { Menu, Moon, Sun, Bell, Film } from 'lucide-react'
import { useAppStore } from '@/store/appStore'
import { VPNStatus } from './VPNStatus'

// Unified logo component pattern (inline for no new file)
function Logo() {
  return (
    <div className="flex items-center gap-2" role="img" aria-label="Media Manager">
      <div className="inline-flex items-center justify-center w-7 h-7 bg-primary text-primary-foreground rounded" aria-hidden="true">
        <Film className="w-4 h-4" aria-hidden="true" />
      </div>
      <span className="text-xl font-bold">Media Manager</span>
    </div>
  )
}

export function Header() {
  const { theme, toggleTheme, toggleSidebar, addToast } = useAppStore()

  const handleNotifications = () => {
    addToast('No new notifications', 'info')
  }

  return (
    <header className="sticky top-0 z-50 w-full border-b bg-background/95 backdrop-blur supports-[backdrop-filter]:bg-background/60">
      <div className="flex h-14 items-center px-4 gap-4">
        <button
          onClick={toggleSidebar}
          aria-label="Toggle sidebar"
          title="Toggle sidebar"
          className="inline-flex items-center justify-center rounded-md text-sm font-medium transition-colors hover:bg-accent hover:text-accent-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 h-9 w-9"
        >
          <Menu className="h-5 w-5" aria-hidden="true" />
        </button>
        
        <Logo />

        <div className="flex flex-1 items-center justify-end gap-2">
          <VPNStatus />
          
          <button
            onClick={toggleTheme}
            aria-label={theme === 'dark' ? 'Switch to light mode' : 'Switch to dark mode'}
            title={theme === 'dark' ? 'Switch to light mode' : 'Switch to dark mode'}
            className="inline-flex items-center justify-center rounded-md text-sm font-medium transition-colors hover:bg-accent hover:text-accent-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 h-9 w-9"
          >
            {theme === 'dark' ? <Sun className="h-5 w-5" aria-hidden="true" /> : <Moon className="h-5 w-5" aria-hidden="true" />}
          </button>
          
          <button 
            onClick={handleNotifications}
            aria-label="Notifications" 
            title="Notifications (click for status)"
            className="inline-flex items-center justify-center rounded-md text-sm font-medium transition-colors hover:bg-accent hover:text-accent-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 h-9 w-9"
          >
            <Bell className="h-5 w-5" aria-hidden="true" />
          </button>
        </div>
      </div>
    </header>
  )
}