interface DiscoverRowProps {
  section: DiscoverSection
  filters: Filters
  hideAdult: boolean
  usedIds: Set<number>
}

function DiscoverRow({ section, filters, hideAdult, usedIds }: DiscoverRowProps) {
  const scrollRef = useRef<HTMLDivElement>(null)
  const [canScrollLeft, setCanScrollLeft] = useState(false)
  const [canScrollRight, setCanScrollRight] = useState(false)

  const isTVSection = section.type === 'tv'

  const { data, isLoading, fetchNextPage, hasNextPage, isFetchingNextPage } = useInfiniteQuery<DiscoverItem[], Error>({
    queryKey: ['discover', section.endpoint, filters],
    initialPageParam: 1,
    queryFn: async ({ pageParam }) => {
      const baseUrl = new URL(section.endpoint, window.location.origin)
      baseUrl.searchParams.set('page', String(pageParam))
      if (filters.genre) baseUrl.searchParams.set('with_genres', String(filters.genre))
      if (filters.minYear) baseUrl.searchParams.set('min_year', String(filters.minYear))
      if (filters.maxYear) baseUrl.searchParams.set('max_year', String(filters.maxYear))
      if (filters.minRating) baseUrl.searchParams.set('min_rating', String(filters.minRating))
      const res = await fetch(baseUrl.toString())
      if (!res.ok) throw new Error('Failed to fetch discover')
      const json = await res.json()
      return json.results || []
    },
    staleTime: 5 * 60 * 1000,
    getNextPageParam: (_lastPage, allPages) => {
      if (allPages.length >= 5) return undefined
      return allPages.length + 1
    },
  })

  const items: DiscoverItem[] = []
  const seenInRow = new Set<number>()
  data?.pages.forEach((page) => {
    page.forEach((item) => {
      if (hideAdult && isAdultContent(item)) return
      if (usedIds.has(item.id)) return
      if (seenInRow.has(item.id)) return
      seenInRow.add(item.id)
      items.push(item)
    })
  })

  const updateScrollState = () => {
    const el = scrollRef.current
    if (!el) return
    const left = el.scrollLeft > 2
    const right = el.scrollLeft + el.clientWidth < el.scrollWidth - 2
    setCanScrollLeft(left)
    setCanScrollRight(right)
  }

  const scrollByAmount = (amount: number) => {
    const el = scrollRef.current
    if (!el) return
    const wasNearEnd = el.scrollLeft + el.clientWidth >= el.scrollWidth - 600
    el.scrollBy({ left: amount, behavior: 'smooth' })
    if (wasNearEnd && hasNextPage && !isFetchingNextPage) {
      fetchNextPage()
    }
    setTimeout(updateScrollState, 350)
  }

  // Netflix-style near-end load: trigger next page when user scrolls near right edge
  const handleScroll = useCallback(() => {
    updateScrollState()
    const el = scrollRef.current
    if (!el || !hasNextPage || isFetchingNextPage) return
    const nearEnd = el.scrollLeft + el.clientWidth >= el.scrollWidth - 600
    if (nearEnd) {
      fetchNextPage()
    }
  }, [fetchNextPage, hasNextPage, isFetchingNextPage])

  useEffect(() => {
    const el = scrollRef.current
    if (!el) return
    const t = setTimeout(updateScrollState, 80)
    const t2 = setTimeout(updateScrollState, 280)
    const t3 = setTimeout(updateScrollState, 900)
    const onResize = () => updateScrollState()
    window.addEventListener('resize', onResize)
    return () => {
      window.removeEventListener('resize', onResize)
      clearTimeout(t)
      clearTimeout(t2)
      clearTimeout(t3)
    }
  }, [data])

  if (isLoading) {
    return (
      <div className="mb-8">
        <SectionHeader section={section} />
        <div className="flex gap-4 overflow-hidden">
          {Array.from({ length: 6 }).map((_, i) => (
            <div key={i} className="flex-shrink-0 w-[180px]">
              <div className="aspect-[2/3] bg-muted rounded-lg animate-pulse" />
              <div className="h-4 w-3/4 bg-muted rounded mt-2 animate-pulse" />
            </div>
          ))}
        </div>
      </div>
    )
  }

  const visible = items.slice(0, 12)

  if (visible.length === 0) {
    return (
      <div className="mb-8">
        <SectionHeader section={section} />
        <p className="text-muted-foreground px-4">No items match the current filters</p>
      </div>
    )
  }

  return (
    <div id={section.title.toLowerCase().replace(/\s+/g, '-')} className="mb-8 scroll-mt-40">
      <SectionHeader section={section} />

      <div className="relative group">
        {canScrollLeft && (
          <button
            type="button"
            onClick={() => scrollByAmount(-320)}
            aria-label={`Scroll left in ${section.title}`}
            title="Scroll left"
            className="absolute left-2 top-1/2 -translate-y-1/2 z-20 flex h-9 w-9 items-center justify-center rounded-full bg-background/90 text-foreground border border-border/60 opacity-80 hover:opacity-100 group-hover:opacity-100 transition-all focus:outline-none focus:ring-2 focus:ring-ring shadow-lg"
          >
            <ChevronLeft className="w-5 h-5" aria-hidden="true" />
          </button>
        )}
        {canScrollLeft && (
          <div className="absolute left-0 top-0 bottom-0 w-10 bg-gradient-to-r from-background/95 to-transparent pointer-events-none z-10 rounded-l-lg transition-opacity" />
        )}

        <div
          ref={scrollRef}
          role="region"
          aria-label={`${section.title} scrollable row`}
          className="flex gap-4 overflow-x-auto pb-4 px-4 scrollbar-hide [-ms-overflow-style:none] [scrollbar-width:none] [&::-webkit-scrollbar]:hidden"
          onScroll={handleScroll}
        >
          {visible.map((item) => {
            const isTV = item.media_type === 'tv' || isTVSection
            return (
              <Link
                key={item.id}
                to={`/${isTV ? 'tv' : 'movie'}/${item.id}`}
                className="flex-shrink-0 w-[180px] group/card cursor-pointer focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring rounded-lg"
                aria-label={`${item.title || item.name} (${item.release_date?.substring(0, 4) || item.first_air_date?.substring(0, 4) || 'N/A'}) ${isTV ? 'TV' : 'movie'}, rated ${item.vote_average.toFixed(1)}`}
              >
                <div className={`relative aspect-[2/3] rounded-lg overflow-hidden bg-muted transition-all duration-200 shadow-md group-hover/card:shadow-xl group-hover/card:-translate-y-0.5 ${isTV ? 'ring-1 ring-violet-500/40' : 'ring-1 ring-border'}`}>
                  {item.poster_path ? (
                    <img
                      src={`https://image.tmdb.org/t/p/w500${item.poster_path}`}
                      alt={item.title || item.name}
                      className="w-full h-full object-cover transition-transform duration-300 group-hover/card:scale-105 outline outline-1 outline-black/10 dark:outline-white/10"
                      loading="lazy"
                      onError={(e) => {
                        const target = e.currentTarget
                        target.style.display = 'none'
                        const fallback = target.nextElementSibling as HTMLElement | null
                        if (fallback) fallback.style.display = 'flex'
                      }}
                    />
                  ) : null}
                  <div
                    className={`w-full h-full flex-col items-center justify-center bg-muted text-foreground p-2 border-2 border-dashed border-border ${item.poster_path ? 'hidden' : 'flex'}`}
                    aria-hidden={!!item.poster_path}
                  >
                    <Film className="w-14 h-14 mb-2" aria-hidden="true" />
                    <p className="text-[10px] text-center line-clamp-3 leading-relaxed font-medium">{item.title || item.name || 'No poster'}</p>
                  </div>
                  {isTV && (
                    <div className="absolute top-2 left-2 px-1.5 py-px text-[9px] font-semibold tracking-[1px] bg-violet-600/90 text-white rounded" aria-hidden="true">TV</div>
                  )}
                  {!isTV && (
                    <div className="absolute top-2 left-2 px-1.5 py-px text-[9px] font-semibold tracking-[1px] bg-emerald-600/80 text-white rounded" aria-hidden="true">MOVIE</div>
                  )}
                  <div className="absolute bottom-2 right-2 flex items-center gap-0.5 rounded bg-background/80 px-1.5 py-0.5 text-yellow-400 border border-border/30" aria-hidden="true">
                    <Star className="w-3 h-3 fill-current" />
                    <span className="text-[11px] font-semibold tabular-nums">{item.vote_average.toFixed(1)}</span>
                  </div>
                  <div className={`absolute inset-0 bg-gradient-to-t from-black/70 via-transparent to-transparent opacity-0 group-hover/card:opacity-100 transition-opacity duration-300`} aria-hidden="true" />
                </div>
                <h3 className="mt-2 text-sm font-semibold text-foreground line-clamp-2 group-hover/card:text-emerald-500 transition-colors">
                  {item.title || item.name}
                </h3>
                <p className="text-xs text-muted-foreground" aria-hidden="true">
                  {item.release_date?.substring(0, 4) || item.first_air_date?.substring(0, 4) || 'N/A'}
                </p>
              </Link>
            )
          })}
          {isFetchingNextPage && (
            <div className="flex-shrink-0 w-[180px] flex items-center justify-center">
              <div className="w-8 h-8 border-2 border-emerald-500 border-t-transparent rounded-full animate-spin" aria-label="Loading more" />
            </div>
          )}
        </div>

        {canScrollRight && (
          <button
            type="button"
            onClick={() => scrollByAmount(320)}
            aria-label={`Scroll right in ${section.title}`}
            title="Scroll right"
            className="absolute right-2 top-1/2 -translate-y-1/2 z-20 flex h-9 w-9 items-center justify-center rounded-full bg-background/90 text-foreground border border-border/60 opacity-80 hover:opacity-100 group-hover:opacity-100 transition-all focus:outline-none focus:ring-2 focus:ring-ring shadow-lg"
          >
            <ChevronRight className="w-5 h-5" aria-hidden="true" />
          </button>
        )}
        {canScrollRight && (
          <div className="absolute right-0 top-0 bottom-0 w-10 bg-gradient-to-l from-background/95 to-transparent pointer-events-none z-10 rounded-r-lg transition-opacity" />
        )}
      </div>
    </div>
  )
}

export function Discover() {
  const [activeTab, setActiveTab] = useState<'all' | 'movie' | 'tv'>('all')
  const [showFilters, setShowFilters] = useState(false)
  const [hideAdult, setHideAdult] = useState(true)
  const [filters, setFilters] = useState<Filters>({
    genre: null,
    minYear: null,
    maxYear: null,
    minRating: null,
  })
  const [showBackToTop, setShowBackToTop] = useState(false)
  useEffect(() => {
    const onScroll = () => setShowBackToTop(window.scrollY > 420)
    window.addEventListener('scroll', onScroll, { passive: true })
    return () => window.removeEventListener('scroll', onScroll)
  }, [])

  const scrollToTop = () => window.scrollTo({ top: 0, behavior: 'smooth' })

  const currentYear = new Date().getFullYear()
  const years = Array.from({ length: 50 }, (_, i) => currentYear - i)
  const ratings = [1, 2, 3, 4, 5, 6, 7, 8, 9]

  const baseGenres = activeTab === 'tv' ? tvGenres : activeTab === 'movie' ? movieGenres : [...movieGenres, ...tvGenres]
  const activeGenres = activeTab === 'all'
    ? Array.from(new Map(baseGenres.map(g => [g.id, g])).values())
    : baseGenres

  useEffect(() => {
    if (filters.genre != null) {
      const isValid = activeGenres.some(g => g.id === filters.genre)
      if (!isValid) {
        setFilters(prev => ({ ...prev, genre: null }))
      }
    }
  }, [activeTab, activeGenres])

  const filteredSections = sections.filter(section => {
    if (activeTab === 'all') return true
    return section.type === activeTab
  })
  const displaySections = (activeTab === 'all' || activeTab === 'movie')
    ? [...filteredSections, hiddenGemsSection]
    : filteredSections

  const hasActiveFilters = filters.genre || filters.minYear || filters.maxYear || filters.minRating || hideAdult

  const clearFilters = () => {
    setFilters({ genre: null, minYear: null, maxYear: null, minRating: null })
    setHideAdult(false)
  }

  const getActiveChipLabel = (key: keyof Filters, val: number | null) => {
    if (!val) return ''
    if (key === 'genre') return activeGenres.find(g => g.id === val)?.name || 'Genre'
    if (key === 'minYear') return `≥${val}`
    if (key === 'maxYear') return `≤${val}`
    if (key === 'minRating') return `${val}+`
    return String(val)
  }

  const removeFilter = (key: keyof Filters) => {
    setFilters(prev => ({ ...prev, [key]: null }))
  }

  const getSectionId = (title: string) => title.toLowerCase().replace(/\s+/g, '-')

  return (
    <div className="min-h-screen bg-background">
      <div className="relative bg-background border-b border-border px-8 py-8" role="banner" aria-label="Discover hero">
        <motion.h1
          initial={{ opacity: 0, y: 10 }}
          animate={{ opacity: 1, y: 0 }}
          className="text-3xl font-bold text-foreground mb-1"
        >
          Discover
        </motion.h1>
        <motion.p
          initial={{ opacity: 0, y: 10 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.1 }}
          className="text-muted-foreground"
        >
          Explore trending movies and TV shows
        </motion.p>
      </div>

      <div className="sticky top-0 z-40 bg-background/95 backdrop-blur-md border-b border-border px-4 py-3">
        <div className="flex items-center justify-between">
          <div role="tablist" aria-label="Discover content type" className="flex gap-2">
            {(['all', 'movie', 'tv'] as const).map((tab) => (
              <button
                type="button"
                key={tab}
                id={`tab-${tab}`}
                role="tab"
                aria-selected={activeTab === tab}
                aria-controls={`discover-panel-${tab}`}
                onClick={() => setActiveTab(tab)}
                className={`px-6 py-2 rounded-full text-sm font-semibold uppercase tracking-wider transition-all duration-300 ${
                  activeTab === tab
                    ? 'bg-primary text-primary-foreground'
                    : 'bg-muted text-foreground hover:bg-accent'
                }`}
              >
                {tab === 'all' ? 'All' : tab === 'movie' ? 'MOVIES' : 'TV SHOWS'}
              </button>
            ))}
          </div>
          <div className="flex items-center gap-2">
            {hasActiveFilters && (
              <button
                type="button"
                onClick={clearFilters}
                className="flex items-center gap-1 px-3 py-2 bg-destructive/20 text-destructive rounded-full text-sm hover:bg-destructive/30 transition-colors"
                aria-label="Clear all filters"
              >
                <X className="w-4 h-4" aria-hidden="true" />
                Clear
              </button>
            )}
            <button
              type="button"
              onClick={() => setHideAdult(!hideAdult)}
              className={`flex items-center gap-2 px-4 py-2 rounded-full text-sm font-semibold transition-colors ${
                hideAdult
                  ? 'bg-emerald-500 text-black'
                  : 'bg-muted text-foreground hover:bg-accent'
              }`}
              aria-pressed={hideAdult}
              aria-label={hideAdult ? 'Show adult content' : 'Hide adult content'}
            >
              {hideAdult ? 'Hide Adult' : 'Show Adult'}
            </button>

            <button
              type="button"
              onClick={() => setShowFilters(!showFilters)}
              className={`flex items-center gap-2 px-4 py-2 rounded-full text-sm font-semibold transition-colors ${
                showFilters || [filters.genre, filters.minYear, filters.maxYear, filters.minRating].some(Boolean)
                  ? 'bg-emerald-500 text-black'
                  : 'bg-muted text-foreground hover:bg-accent'
              }`}
              aria-expanded={showFilters}
              aria-label="Toggle filters panel"
              aria-controls="discover-filter-panel"
            >
              <SlidersHorizontal className="w-4 h-4" aria-hidden="true" />
              Filters
              {[filters.genre, filters.minYear, filters.maxYear, filters.minRating].some(Boolean) && (
                <span className="w-5 h-5 bg-background text-emerald-500 rounded-full text-xs flex items-center justify-center font-bold" aria-label={`${[filters.genre, filters.minYear, filters.maxYear, filters.minRating].filter(Boolean).length} active filters`}>
                  {[filters.genre, filters.minYear, filters.maxYear, filters.minRating].filter(Boolean).length}
                </span>
              )}
            </button>
          </div>
        </div>

        {hasActiveFilters && (
          <div className="flex flex-wrap gap-2 pt-3 pb-1">
            {(['genre', 'minYear', 'maxYear', 'minRating'] as const).map((key) => {
              const val = filters[key]
              if (!val) return null
              const label = getActiveChipLabel(key, val)
              return (
                <span
                  key={key}
                  className="inline-flex items-center gap-1 px-2.5 py-1 rounded-full bg-muted text-xs text-foreground border border-border"
                >
                  {label}
                  <button
                    type="button"
                    onClick={() => removeFilter(key)}
                    aria-label={`Remove ${key} filter`}
                    className="ml-0.5 hover:text-foreground"
                  >
                    <X className="w-3 h-3" aria-hidden="true" />
                  </button>
                </span>
              )
            })}
            {hideAdult && (
              <span className="inline-flex items-center gap-1 px-2.5 py-1 rounded-full bg-muted text-xs text-foreground border border-border">
                Adult hidden
                <button
                  type="button"
                  onClick={() => setHideAdult(false)}
                  aria-label="Remove adult filter"
                  className="ml-0.5 hover:text-foreground"
                >
                  <X className="w-3 h-3" aria-hidden="true" />
                </button>
              </span>
            )}
          </div>
        )}

        <AnimatePresence>
          {showFilters && (
            <motion.div
              id="discover-filter-panel"
              initial={{ height: 0, opacity: 0 }}
              animate={{ height: 'auto', opacity: 1 }}
              exit={{ height: 0, opacity: 0 }}
              transition={{ duration: 0.2 }}
              className="overflow-hidden"
            >
              <div className="pt-4 pb-2 grid grid-cols-1 md:grid-cols-4 gap-4">
                <div>
                  <label htmlFor="filter-genre" className="text-muted-foreground text-sm mb-2 block">Genre</label>
                  <select
                    id="filter-genre"
                    value={filters.genre || ''}
                    onChange={(e) => setFilters({ ...filters, genre: e.target.value ? parseInt(e.target.value) : null })}
                    className="w-full bg-muted text-foreground rounded-lg px-3 py-2 border border-border focus:border-emerald-500 focus:outline-none"
                    aria-label="Filter by genre"
                  >
                    <option value="">All Genres</option>
                    {activeGenres.map(genre => (
                      <option key={genre.id} value={genre.id}>{genre.name}</option>
                    ))}
                  </select>
                </div>

                <div>
                  <label htmlFor="filter-min-year" className="text-muted-foreground text-sm mb-2 block">From Year</label>
                  <select
                    id="filter-min-year"
                    value={filters.minYear || ''}
                    onChange={(e) => setFilters({ ...filters, minYear: e.target.value ? parseInt(e.target.value) : null })}
                    className="w-full bg-muted text-foreground rounded-lg px-3 py-2 border border-border focus:border-emerald-500 focus:outline-none"
                    aria-label="Filter from year"
                  >
                    <option value="">Any</option>
                    {years.map(year => (
                      <option key={year} value={year}>{year}</option>
                    ))}
                  </select>
                </div>

                <div>
                  <label htmlFor="filter-max-year" className="text-muted-foreground text-sm mb-2 block">To Year</label>
                  <select
                    id="filter-max-year"
                    value={filters.maxYear || ''}
                    onChange={(e) => setFilters({ ...filters, maxYear: e.target.value ? parseInt(e.target.value) : null })}
                    className="w-full bg-muted text-foreground rounded-lg px-3 py-2 border border-border focus:border-emerald-500 focus:outline-none"
                    aria-label="Filter to year"
                  >
                    <option value="">Any</option>
                    {years.map(year => (
                      <option key={year} value={year}>{year}</option>
                    ))}
                  </select>
                </div>

                <div>
                  <label htmlFor="filter-min-rating" className="text-muted-foreground text-sm mb-2 block">Min Rating</label>
                  <select
                    id="filter-min-rating"
                    value={filters.minRating || ''}
                    onChange={(e) => setFilters({ ...filters, minRating: e.target.value ? parseInt(e.target.value) : null })}
                    className="w-full bg-muted text-foreground rounded-lg px-3 py-2 border border-border focus:border-emerald-500 focus:outline-none"
                    aria-label="Filter minimum rating"
                  >
                    <option value="">Any</option>
                    {ratings.map(rating => (
                      <option key={rating} value={rating}>{rating}+ Stars</option>
                    ))}
                  </select>
                </div>
              </div>
            </motion.div>
          )}
        </AnimatePresence>

        {displaySections.length > 1 && (
          <div className="pt-3 flex gap-x-3 gap-y-1 text-xs overflow-x-auto text-muted-foreground" role="navigation" aria-label="Jump to sections">
            {displaySections.map((s) => (
              <a
                key={s.endpoint}
                href={`#${getSectionId(s.title)}`}
                onClick={(e) => {
                  e.preventDefault()
                  const el = document.getElementById(getSectionId(s.title))
                  if (el) {
                    const headerOffset = 180
                    const top = el.getBoundingClientRect().top + window.scrollY - headerOffset
                    window.scrollTo({ top, behavior: 'smooth' })
                  }
                }}
                className="hover:text-foreground whitespace-nowrap transition-colors underline-offset-2 hover:underline"
              >
                {s.title.replace(' Movies', '').replace(' TV Shows', '').replace(' TV', '')}
              </a>
            ))}
          </div>
        )}
      </div>

      <div className="py-6" role="tabpanel" id={`discover-panel-${activeTab === 'movie' ? 'movies' : activeTab}`} aria-labelledby={`tab-${activeTab}`}>
        <div>
          {displaySections.map((section) => (
            <DiscoverRow
              key={section.endpoint}
              section={section}
              filters={filters}
              hideAdult={hideAdult}
              usedIds={new Set()}
            />
          ))}
        </div>
      </div>

      {showBackToTop && (
        <button
          type="button"
          onClick={scrollToTop}
          aria-label="Back to top"
          title="Back to top"
          className="fixed bottom-6 right-6 z-50 flex items-center justify-center h-11 w-11 rounded-full bg-muted hover:bg-accent text-foreground shadow-lg border border-border transition focus:outline-none focus:ring-2 focus:ring-ring"
        >
          <ArrowUp className="w-5 h-5" aria-hidden="true" />
        </button>
      )}
    </div>
  )
}
