import { useState, useMemo } from 'react'
import { Link } from 'react-router-dom'
import { Card, CardContent } from '@/components/ui/Card'
import { Button } from '@/components/ui/Button'
import { Input } from '@/components/ui/Input'
import { PosterImage } from '@/components/PosterImage'
import { useLibrary, useReprocessLibrary, useFetchAllPosters } from '@/hooks/useApi'
import { useAppStore } from '@/store/appStore'
import { RefreshCw, ImageDown, Search, X, Loader2, Film } from 'lucide-react'

export function Library() {
  const { data: movies, isLoading, isFetching } = useLibrary()
  const { addToast } = useAppStore()
  const reprocessLibrary = useReprocessLibrary()
  const fetchAllPosters = useFetchAllPosters()
  const [filterQuery, setFilterQuery] = useState('')

  const filteredMovies = useMemo(() => {
    if (!filterQuery.trim()) return movies
    const query = filterQuery.toLowerCase()
    return movies?.filter(movie =>
      movie.title.toLowerCase().includes(query)
    )
  }, [movies, filterQuery])

  const getErrorMessage = (error: any): string => {
    return error?.userMessage || error?.message || 'Unknown error'
  }

  const isReprocessing = reprocessLibrary.isPending
  const isFetchingPosters = fetchAllPosters.isPending
  const isProcessing = isReprocessing || isFetchingPosters || isFetching

  const handleReprocess = async () => {
    try {
      await reprocessLibrary.mutateAsync()
      addToast('Library reprocessed successfully', 'success')
    } catch (error: any) {
      addToast(`Failed to reprocess: ${getErrorMessage(error)}`, 'error')
    }
  }

  const handleFetchPosters = async () => {
    try {
      const result = await fetchAllPosters.mutateAsync()
      addToast(
        `Fetched ${result.fetched} posters, ${result.cached} cached, ${result.failed} failed`,
        'success'
      )
    } catch (error: any) {
      addToast(`Failed to fetch posters: ${getErrorMessage(error)}`, 'error')
    }
  }

  if (isLoading) {
    return (
      <div className="space-y-6">
        <div className="flex items-center justify-between">
          <div>
            <h1 className="text-3xl font-bold tracking-tight">Library</h1>
            <p className="text-muted-foreground">Loading your media collection...</p>
          </div>
        </div>
        <div className="grid gap-4 sm:grid-cols-4 lg:grid-cols-6 xl:grid-cols-8">
          {Array.from({ length: 12 }).map((_, i) => (
            <div key={i} className="overflow-hidden rounded-lg border">
              <div className="aspect-[2/3] bg-muted animate-pulse" />
              <div className="p-4 space-y-2">
                <div className="h-4 bg-muted animate-pulse rounded" />
                <div className="h-3 bg-muted animate-pulse rounded w-2/3" />
              </div>
            </div>
          ))}
        </div>
      </div>
    )
  }

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-bold tracking-tight">Library</h1>
          <p className="text-muted-foreground">
            Browse your media collection ({movies?.length || 0} items)
          </p>
        </div>
        <div className="flex gap-2">
          <Button
            variant="outline"
            onClick={handleFetchPosters}
            disabled={isProcessing}
            aria-label="Fetch all posters for library items"
            title="Fetch all posters"
          >
            {isFetchingPosters ? (
              <Loader2 className="mr-2 h-4 w-4 animate-spin" />
            ) : (
              <ImageDown className="mr-2 h-4 w-4" />
            )}
            Fetch Posters
          </Button>
          <Button
            variant="outline"
            onClick={handleReprocess}
            disabled={isReprocessing}
            aria-label="Clean and reprocess library filenames"
            title="Clean filenames"
          >
            {isReprocessing ? (
              <Loader2 className="mr-2 h-4 w-4 animate-spin" />
            ) : (
              <RefreshCw className="mr-2 h-4 w-4" />
            )}
            Clean Filenames
          </Button>
        </div>
      </div>

      {isProcessing && (
        <div className="flex items-center gap-2 text-sm text-muted-foreground">
          <Loader2 className="h-4 w-4 animate-spin" />
          {isReprocessing ? 'Cleaning filenames...' : isFetchingPosters ? 'Fetching all posters...' : 'Refreshing library...'}
        </div>
      )}

      <div className="relative max-w-sm">
        <Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" />
        <Input
          placeholder="Filter library..."
          value={filterQuery}
          onChange={(e) => setFilterQuery(e.target.value)}
          className="pl-9 pr-9"
          disabled={isProcessing}
          aria-label="Filter library items"
        />
        {filterQuery && !isProcessing && (
          <button
            onClick={() => setFilterQuery('')}
            className="absolute right-3 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-foreground"
          >
            <X className="h-4 w-4" />
          </button>
        )}
      </div>

      {filterQuery && filteredMovies && (
        <p className="text-sm text-muted-foreground">
          Showing {filteredMovies.length} of {movies?.length || 0} movies
        </p>
      )}

      <div className="grid gap-4 sm:grid-cols-4 lg:grid-cols-6 xl:grid-cols-8">
        {filteredMovies?.map((movie) => (
          <Card key={movie.path} className="overflow-hidden active:scale-[0.96] transition-transform">
            <div className="aspect-[2/3] relative bg-muted">
              <PosterImage
                src={movie.poster_url}
                alt={movie.title}
                title={movie.title}
                className="absolute inset-0 w-full h-full object-cover"
                showFallbackTitle={false}
              />
            </div>
            <CardContent className="p-4">
              <h3 className="font-semibold line-clamp-2">{movie.title}</h3>
              <div className="flex items-center justify-between mt-2 text-xs text-muted-foreground">
                <span>{movie.size}</span>
                {movie.year ? <span>{movie.year}</span> : <span>—</span>}
                {movie.rating ? (
                  <span className="text-foreground/80 font-medium">{movie.rating}</span>
                ) : (
                  <span>—</span>
                )}
              </div>
            </CardContent>
          </Card>
        ))}
      </div>

      {filteredMovies?.length === 0 && (
        <Card className={filterQuery ? '' : 'border-2 border-dashed'}>
          <CardContent className="p-8 text-center">
            <Film className="h-12 w-12 mx-auto mb-4 text-muted-foreground/60" />
            {filterQuery ? (
              <>
                <p className="font-medium">No movies match "{filterQuery}"</p>
                <p className="text-sm text-muted-foreground mt-1">Try a different search term.</p>
                <Button
                  variant="ghost"
                  size="sm"
                  className="mt-4"
                  onClick={() => setFilterQuery('')}
                >
                  Clear filter
                </Button>
              </>
            ) : (
              <>
                <p className="font-medium">No media files found</p>
                <p className="text-sm text-muted-foreground mt-1 max-w-xs mx-auto">
                  Your library will appear here once you download some media via Discover or Suggestions.
                </p>
                <div className="mt-4 flex gap-2 justify-center">
                  <Link
                    to="/discover"
                    className="inline-flex items-center gap-2 px-3 py-1.5 text-sm bg-primary text-primary-foreground rounded-md hover:bg-primary/90 transition-colors"
                  >
                    Browse Discover
                  </Link>
                  <Link
                    to="/suggestions"
                    className="inline-flex items-center gap-2 px-3 py-1.5 text-sm border rounded-md hover:bg-accent transition-colors"
                  >
                    View Suggestions
                  </Link>
                </div>
              </>
            )}
          </CardContent>
        </Card>
      )}
    </div>
  )
}