import { useRef, useEffect, useMemo } from 'react'
import { Play, Clock } from 'lucide-react'
import type { EPGResponse, EPGChannelResponse, EPGEntry } from '@/types'

interface EPGGridProps {
  epg: EPGResponse
  onSelectProgram: (entry: EPGEntry, channel: EPGChannelResponse) => void
}

const HOUR_HEIGHT = 60          // px per hour
const HOURS_VISIBLE = 8         // show 8 hours at a time
const MINUTE_HEIGHT = HOUR_HEIGHT / 60

function formatTime(iso: string): string {
  const d = new Date(iso)
  return d.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
}

function formatDuration(seconds: number): string {
  const h = Math.floor(seconds / 3600)
  const m = Math.floor((seconds % 3600) / 60)
  if (h > 0) return `${h}h ${m}m`
  return `${m}m`
}

function programWidth(durationSeconds: number): number {
  return Math.max(40, (durationSeconds / 3600) * HOUR_HEIGHT)
}

export function EPGGrid({ epg, onSelectProgram }: EPGGridProps) {
  const scrollRef = useRef<HTMLDivElement>(null)
  const nowRef = useRef<HTMLDivElement>(null)

  const now = useMemo(() => new Date(epg.now), [epg.now])

  // Auto-scroll to current time on mount
  useEffect(() => {
    if (scrollRef.current && nowRef.current) {
      nowRef.current.scrollIntoView({ behavior: 'smooth', inline: 'center', block: 'nearest' })
    }
  }, [epg.channels.length])

  // Compute the time range covered by the EPG
  const timeRange = useMemo(() => {
    let earliest = Infinity
    let latest = -Infinity
    for (const ch of epg.channels) {
      const schedule = ch.schedule || []
      for (const entry of schedule) {
        const s = new Date(entry.start_time).getTime()
        const e = new Date(entry.end_time).getTime()
        if (s < earliest) earliest = s
        if (e > latest) latest = e
      }
    }
    if (!isFinite(earliest)) {
      earliest = now.getTime()
      latest = now.getTime() + 8 * 3600 * 1000
    }
    return { earliest: new Date(earliest), latest: new Date(latest) }
  }, [epg, now])

  // Calculate offset from earliest time in minutes
  function minutesFromStart(time: string): number {
    const d = new Date(time)
    return (d.getTime() - timeRange.earliest.getTime()) / 60000
  }

  // Current time offset for the red line
  const nowOffsetMinutes = (now.getTime() - timeRange.earliest.getTime()) / 60000

  // Render hour markers every hour
  const hourMarkers: { label: string; minutes: number }[] = []
  let cursor = new Date(timeRange.earliest)
  while (cursor < timeRange.latest) {
    hourMarkers.push({
      label: cursor.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
      minutes: (cursor.getTime() - timeRange.earliest.getTime()) / 60000,
    })
    cursor = new Date(cursor.getTime() + 3600 * 1000)
  }

  if (epg.channels.length === 0) {
    return (
      <div className="flex items-center justify-center h-64 text-white/40 text-xl">
        No channels available. Channels will appear once content is available.
      </div>
    )
  }

  return (
    <div className="flex flex-col h-full bg-[#0a0a0a]">
      {/* Header: channel labels column + timed headers */}
      <div className="flex border-b border-white/10 bg-[#121212] sticky top-0 z-20">
        {/* Channel label column */}
        <div className="w-48 flex-shrink-0 p-3 text-sm font-semibold text-white/60 uppercase tracking-wider">
          Channels
        </div>
        {/* Time headers */}
        <div className="flex-1 flex" style={{ minWidth: (HOURS_VISIBLE + 2) * HOUR_HEIGHT }}>
          {hourMarkers.map((h, i) => (
            <div
              key={i}
              className="flex-shrink-0 p-2 text-xs text-white/40 border-l border-white/5"
              style={{ width: HOUR_HEIGHT }}
            >
              {h.label}
            </div>
          ))}
        </div>
      </div>

      {/* Scrollable grid body */}
      <div ref={scrollRef} className="flex-1 overflow-auto">
        <div className="flex">
          {/* Channel sidebar */}
          <div className="w-48 flex-shrink-0 bg-[#0a0a0a] z-10">
            {epg.channels.map((ch) => (
              <div
                key={ch.channel.id}
                className="flex items-center gap-3 h-20 px-4 border-b border-white/5 hover:bg-white/5 transition-colors"
              >
                <span className="text-2xl flex-shrink-0">{ch.channel.icon || '📺'}</span>
                <div className="min-w-0">
                  <div className="text-white font-semibold text-sm truncate">{ch.channel.name}</div>
                  <div className="text-white/40 text-xs truncate">{ch.channel.description}</div>
                </div>
              </div>
            ))}
          </div>

          {/* Program grid */}
          <div className="relative" style={{ minWidth: (HOURS_VISIBLE + 2) * HOUR_HEIGHT }}>
            {epg.channels.map((ch) => (
              <div key={ch.channel.id} className="relative h-20 border-b border-white/5">
                {/* Background grid lines */}
                {hourMarkers.map((h, i) => (
                  <div
                    key={i}
                    className="absolute top-0 bottom-0 border-l border-white/5"
                    style={{ left: h.minutes * MINUTE_HEIGHT, width: 0 }}
                  />
                ))}

                {/* Programs */}
                {(ch.schedule || []).map((entry, i) => {
                  const left = minutesFromStart(entry.start_time) * MINUTE_HEIGHT
                  const width = programWidth(entry.item.duration_seconds)
                  const isNow = entry.is_current
                  const isPast = new Date(entry.end_time) < now

                  return (
                    <button
                      key={`${entry.item.id || i}-${i}`}
                      onClick={() => onSelectProgram(entry, ch)}
                      className={`absolute top-1 bottom-1 rounded-md px-2 py-1 text-left transition-all hover:ring-2 hover:ring-[#1ed760]/50 overflow-hidden ${
                        isNow
                          ? 'bg-[#1ed760]/20 border border-[#1ed760]/40 z-10'
                          : isPast
                          ? 'bg-white/5 border border-white/10 opacity-60'
                          : 'bg-white/10 border border-white/10 hover:bg-white/15'
                      }`}
                      style={{ left, width }}
                    >
                      <div className="flex items-center gap-1 text-xs font-medium text-white truncate">
                        {isNow && <Play className="w-3 h-3 text-[#1ed760] flex-shrink-0" fill="currentColor" />}
                        {entry.item.title}
                      </div>
                      <div className="flex items-center gap-1 text-[10px] text-white/50 mt-0.5">
                        <Clock className="w-2.5 h-2.5" />
                        {formatTime(entry.start_time)} - {formatTime(entry.end_time)}
                        <span className="ml-1">({formatDuration(entry.item.duration_seconds)})</span>
                      </div>
                      {/* Progress bar for current item */}
                      {isNow && entry.progress_percent > 0 && (
                        <div className="absolute bottom-0 left-0 right-0 h-0.5 bg-white/10">
                          <div
                            className="h-full bg-[#1ed760] transition-all"
                            style={{ width: `${entry.progress_percent}%` }}
                          />
                        </div>
                      )}
                    </button>
                  )
                })}
              </div>
            ))}

            {/* Current time indicator line */}
            <div
              ref={nowRef}
              className="absolute top-0 bottom-0 w-0.5 bg-[#1ed760] z-20 shadow-lg shadow-[#1ed760]/50"
              style={{ left: nowOffsetMinutes * MINUTE_HEIGHT }}
            >
              <div className="absolute -top-1 -left-1.5 w-3 h-3 rounded-full bg-[#1ed760]" />
            </div>
          </div>
        </div>
      </div>
    </div>
  )
}
