import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/Card'
import { Button } from '@/components/ui/Button'
import { Badge } from '@/components/ui/Badge'
import { useTasks, useCancelTask, useRestartTask, useDeleteTask, useClearCompletedTasks, useClearFailedTasks } from '@/hooks/useApi'
import { useAppStore } from '@/store/appStore'
import { getStatusBgColor, formatBytes, formatDateTime } from '@/lib/utils'
import { Link } from 'react-router-dom'
import { Pause, Trash2, RotateCcw, CheckCircle, XCircle, Download, Clock, Search, Sparkles } from 'lucide-react'

export function Downloads() {
  const { data: tasks, isLoading } = useTasks()
  const { addToast } = useAppStore()
  
  const cancelTask = useCancelTask()
  const restartTask = useRestartTask()
  const deleteTask = useDeleteTask()
  const clearCompleted = useClearCompletedTasks()
  const clearFailed = useClearFailedTasks()

  const getErrorMessage = (error: any): string => {
    return error?.userMessage || error?.message || 'Unknown error'
  }

  const handleCancel = async (id: number) => {
    try {
      await cancelTask.mutateAsync(id)
      addToast('Task cancelled', 'success')
    } catch (error: any) {
      addToast(`Failed to cancel: ${getErrorMessage(error)}`, 'error')
    }
  }

  const handleRestart = async (id: number) => {
    try {
      await restartTask.mutateAsync(id)
      addToast('Task restarted', 'success')
    } catch (error: any) {
      addToast(`Failed to restart: ${getErrorMessage(error)}`, 'error')
    }
  }

  const handleDelete = async (id: number) => {
    try {
      await deleteTask.mutateAsync(id)
      addToast('Task deleted', 'success')
    } catch (error: any) {
      addToast(`Failed to delete: ${getErrorMessage(error)}`, 'error')
    }
  }

  const handleClearCompleted = async () => {
    try {
      await clearCompleted.mutateAsync()
      addToast('Completed tasks cleared', 'success')
    } catch (error: any) {
      addToast(`Failed to clear: ${getErrorMessage(error)}`, 'error')
    }
  }

  const handleClearFailed = async () => {
    try {
      await clearFailed.mutateAsync()
      addToast('Failed tasks cleared', 'success')
    } catch (error: any) {
      addToast(`Failed to clear: ${getErrorMessage(error)}`, 'error')
    }
  }

  // Compute stats for display and conditional clears
  const completedCount = tasks?.filter((t: any) => t.status === 'completed').length || 0
  const failedCount = tasks?.filter((t: any) => t.status === 'failed').length || 0
  const pendingCount = tasks?.filter((t: any) => t.status === 'pending' || t.status === 'queued').length || 0
  const downloadingCount = tasks?.filter((t: any) => t.status === 'downloading').length || 0

  if (isLoading) {
    return (
      <div className="flex items-center justify-center py-12">
        <div className="text-muted-foreground">Loading downloads...</div>
      </div>
    )
  }

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-bold tracking-tight">Downloads</h1>
          <p className="text-muted-foreground">
            Manage your download queue
          </p>
        </div>
        <div className="flex gap-2">
          {completedCount > 0 && (
            <Button
              variant="outline"
              onClick={handleClearCompleted}
              disabled={clearCompleted.isPending}
            >
              <CheckCircle className="mr-2 h-4 w-4" />
              Clear Completed
            </Button>
          )}
          {failedCount > 0 && (
            <Button
              variant="outline"
              onClick={handleClearFailed}
              disabled={clearFailed.isPending}
            >
              <XCircle className="mr-2 h-4 w-4" />
              Clear Failed
            </Button>
          )}
        </div>
      </div>

      {/* Stats row - unified style */}
      <div className="grid gap-4 md:grid-cols-4">
        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Downloading</CardTitle>
            <Download className="h-4 w-4 text-blue-500" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{downloadingCount}</div>
          </CardContent>
        </Card>
        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Pending</CardTitle>
            <Clock className="h-4 w-4 text-yellow-500" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{pendingCount}</div>
          </CardContent>
        </Card>
        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Completed</CardTitle>
            <CheckCircle className="h-4 w-4 text-green-500" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{completedCount}</div>
          </CardContent>
        </Card>
        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Failed</CardTitle>
            <XCircle className="h-4 w-4 text-red-500" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{failedCount}</div>
          </CardContent>
        </Card>
      </div>

      <div className="space-y-4">
        {tasks?.map((task) => (
          <Card key={task.id}>
            <CardContent className="p-6">
              <div className="flex items-start justify-between">
                <div className="space-y-1">
                  <h3 className="font-semibold">{task.title}</h3>
                  <div className="flex items-center gap-2 text-sm text-muted-foreground">
                    <Badge className={getStatusBgColor(task.status)}>
                      {task.status}
                    </Badge>
                    <span>{formatBytes(task.size)}</span>
                    <span>•</span>
                    <span>{task.seeders} seeders</span>
                    {task.started_at && (
                      <>
                        <span>•</span>
                        <span>Started {formatDateTime(task.started_at)}</span>
                      </>
                    )}
                  </div>
                </div>

                <div className="flex items-center gap-2">
                  {task.status === 'downloading' && (
                    <Button
                      variant="outline"
                      size="icon"
                      onClick={() => handleCancel(task.id)}
                      disabled={cancelTask.isPending}
                    >
                      <Pause className="h-4 w-4" />
                    </Button>
                  )}
                  
                  {(task.status === 'failed' || task.status === 'cancelled') && (
                    <Button
                      variant="outline"
                      size="icon"
                      onClick={() => handleRestart(task.id)}
                      disabled={restartTask.isPending}
                    >
                      <RotateCcw className="h-4 w-4" />
                    </Button>
                  )}

                  <Button
                    variant="outline"
                    size="icon"
                    onClick={() => handleDelete(task.id)}
                    disabled={deleteTask.isPending}
                  >
                    <Trash2 className="h-4 w-4" />
                  </Button>
                </div>
              </div>

              {/* Progress bar */}
              <div className="mt-4">
                <div className="h-2 w-full rounded-full bg-secondary">
                  <div
                    className="h-2 rounded-full bg-primary transition-all"
                    style={{ width: `${task.progress}%` }}
                  />
                </div>
                <p className="mt-1 text-sm text-muted-foreground">
                  {task.progress.toFixed(1)}% complete
                </p>
              </div>

              {task.error && (
                <p className="mt-2 text-sm text-red-500">
                  Error: {task.error}
                </p>
              )}
            </CardContent>
          </Card>
        ))}

        {tasks?.length === 0 && (
          <Card className="border-2 border-dashed">
            <CardContent className="p-8 text-center">
              <Download className="h-12 w-12 mx-auto mb-4 text-muted-foreground/50" />
              <h3 className="text-lg font-semibold mb-2">No downloads yet</h3>
              <p className="text-sm text-muted-foreground mb-4 max-w-sm mx-auto">
                Your download queue is empty. Search for torrents or generate AI suggestions to start downloading.
              </p>
              <div className="flex flex-wrap gap-2 justify-center">
                <Link to="/search">
                  <Button variant="outline" size="sm">
                    <Search className="mr-2 h-4 w-4" />
                    Search Torrents
                  </Button>
                </Link>
                <Link to="/suggestions">
                  <Button variant="outline" size="sm">
                    <Sparkles className="mr-2 h-4 w-4" />
                    Generate Suggestions
                  </Button>
                </Link>
              </div>
            </CardContent>
          </Card>
        )}
      </div>
    </div>
  )
}