import { useState, useEffect, useRef, useCallback } from 'react'
import { useQuery } from '@tanstack/react-query'
import { motion } from 'framer-motion'
import { Play, Star, TrendingUp, Tv, Clock, Settings as SettingsIcon, Search, Home, Heart, History, Radio } from 'lucide-react'
import { Link, useNavigate } from 'react-router-dom'
import { PosterImage } from '@/components/PosterImage'

interface TVItem {
  id: number
  title?: string
  name?: string
  poster_path: string
  backdrop_path: string
  vote_average: number
  release_date?: string
  first_air_date?: string
  media_type: string
}

interface TVSection {
  title: string
  endpoint: string
  icon: React.ReactNode
}

const sections: TVSection[] = [
  { title: 'Trending Movies', endpoint: '/api/discover/movies/trending', icon: <TrendingUp className="w-8 h-8" /> },
  { title: 'Popular Movies', endpoint: '/api/discover/movies/popular', icon: <Star className="w-8 h-8" /> },
  { title: 'Now Playing', endpoint: '/api/discover/movies/now_playing', icon: <Play className="w-8 h-8" /> },
  { title: 'Trending TV', endpoint: '/api/discover/tv/trending', icon: <Tv className="w-8 h-8" /> },
  { title: 'Popular TV', endpoint: '/api/discover/tv/popular', icon: <Star className="w-8 h-8" /> },
  { title: 'Airing Today', endpoint: '/api/discover/tv/airing_today', icon: <Clock className="w-8 h-8" /> },
]

// Navigation items for sidebar (use valid routes to avoid blank pages; tv/* full-screen)
const navItems = [
  { id: 'home', label: 'Home', icon: <Home className="w-10 h-10" />, path: '/tv' },
  { id: 'guide', label: 'TV Guide', icon: <Radio className="w-10 h-10" />, path: '/tv-guide' },
  { id: 'discover', label: 'Discover', icon: <Search className="w-10 h-10" />, path: '/discover' },
  { id: 'watchlist', label: 'Watchlist', icon: <Heart className="w-10 h-10" />, path: '/watchlist' },
  { id: 'history', label: 'History', icon: <History className="w-10 h-10" />, path: '/' },
  { id: 'settings', label: 'Settings', icon: <SettingsIcon className="w-10 h-10" />, path: '/settings' },
]

// Unified logo (matches Header/Login using Film icon + ARIA for consistency)
function TVLogo({ collapsed }: { collapsed: boolean }) {
  return (
    <div className="flex items-center gap-4" aria-label="Media Manager TV Interface">
      <div className="inline-flex items-center justify-center w-14 h-14 bg-primary text-primary-foreground rounded-2xl flex-shrink-0" aria-hidden="true">
        <Play className="w-8 h-8 text-black ml-1" fill="currentColor" />
      </div>
      {!collapsed && (
        <span className="text-2xl font-bold">Media</span>
      )}
    </div>
  )
}

function TVRow({ section, isFocused, focusedIndex, onItemFocus }: { section: TVSection; isFocused: boolean; focusedIndex: number; onItemFocus?: (path: string | null) => void }) {
  const scrollRef = useRef<HTMLDivElement>(null)
  const { data, isLoading, isError } = useQuery({
    queryKey: ['tv-discover', section.endpoint],
    queryFn: async () => {
      const response = await fetch(section.endpoint)
      if (!response.ok) throw new Error('Failed to fetch')
      return response.json()
    },
    staleTime: 1000 * 60 * 5,
  })

  const items: TVItem[] = data?.results?.slice(0, 8) || []

  // Focus management: scroll focused card into view + actually focus() for Enter/keyboard/screenreader; report path (unify d-pad)
  useEffect(() => {
    if (isFocused && items.length > 0) {
      const safeIndex = Math.min(focusedIndex, items.length - 1)
      const item = items[safeIndex]
      if (item) {
        onItemFocus?.(`/${item.media_type === 'tv' ? 'tv' : 'movie'}/${item.id}`)
      }
      // Scroll + focus the target link for true focus state + reliable Enter activation
      if (scrollRef.current) {
        const cards = scrollRef.current.querySelectorAll('a')
        const target = cards[safeIndex] as HTMLElement | undefined
        if (target) {
          target.scrollIntoView({ behavior: 'smooth', block: 'nearest', inline: 'center' })
          // focus even with tabIndex=-1 for managed nav (aids ARIA + Enter)
          target.focus({ preventScroll: true })
        }
      }
    } else if (!isFocused) {
      onItemFocus?.(null)
    }
  }, [isFocused, focusedIndex, items, onItemFocus])

  if (isLoading) {
    return (
      <div className="mb-12" aria-busy="true" aria-label={`Loading ${section.title}`}>
        <div className="h-10 w-64 bg-white/10 rounded animate-pulse mb-6" />
        <div className="flex gap-6">
          {Array.from({ length: 6 }).map((_, i) => (
            <div key={i} className="flex-shrink-0 w-[280px]">
              <div className="aspect-[2/3] bg-white/10 rounded-xl animate-pulse" />
            </div>
          ))}
        </div>
      </div>
    )
  }

  if (isError) {
    return (
      <div className="mb-12 px-12">
        <div className="h-10 w-64 bg-white/10 rounded mb-6" />
        <div className="text-[#b3b3b3]">Failed to load {section.title.toLowerCase()}</div>
      </div>
    )
  }

  return (
    <div className="mb-12">
      <div className="flex items-center gap-4 mb-6 px-12">
        <span className="text-[#1ed760]">{section.icon}</span>
        <h2 className="text-3xl font-bold text-white">{section.title}</h2>
      </div>

      <div ref={scrollRef} className="flex gap-6 overflow-x-auto pb-6 px-12 scrollbar-hide" role="list" aria-label={section.title}>
        {items.length === 0 ? (
          <div className="px-4 py-8 text-[#b3b3b3] text-lg">No items available</div>
        ) : (
          items.map((item, index) => {
            const isItemFocused = isFocused && index === focusedIndex
            return (
              <Link
                key={item.id}
                to={`/${item.media_type === 'tv' ? 'tv' : 'movie'}/${item.id}`}
                className={`group flex-shrink-0 w-[280px] transition-all duration-300 outline-none focus-visible:ring-4 focus-visible:ring-[#1ed760] rounded-xl hover:scale-105 hover:z-10 focus:scale-105 focus:z-10 ${
                  isItemFocused ? 'scale-110 z-10 ring-4 ring-[#1ed760] shadow-2xl shadow-[#1ed760]/20' : 'scale-100'
                }`}
                tabIndex={-1}
                aria-label={`${item.title || item.name} - rating ${(item.vote_average ? (item.vote_average).toFixed(1) : 'N/A')}`}
                role="listitem"
              >
                <div className={`relative aspect-[2/3] rounded-xl overflow-hidden bg-[#1f1f1f] transition-all group-hover:ring-2 group-focus-visible:ring-2 group-hover:ring-[#1ed760] group-focus-visible:ring-[#1ed760]`}>
                  <PosterImage
                    src={item.poster_path ? `https://image.tmdb.org/t/p/w500${item.poster_path}` : undefined}
                    alt={item.title || item.name || ''}
                    className="absolute inset-0 w-full h-full object-cover"
                    showFallbackTitle={true}
                  />
                  {/* Always-visible rating (not hover-only) for D-pad/keyboard/TV affordance + better contrast (ux-design-reviewer); hover/focus enhances */}
                  <div className="absolute inset-0 bg-gradient-to-t from-black/90 via-transparent to-transparent">
                    <div className="absolute bottom-4 left-4 right-4">
                      <div className="flex items-center gap-2 text-yellow-400 mb-2">
                        <Star className="w-6 h-6 fill-current" />
                        <span className="text-xl font-bold">{(item.vote_average || 0).toFixed(1)}</span>
                      </div>
                    </div>
                  </div>
                </div>
                <h3 className={`mt-3 text-xl font-semibold line-clamp-2 transition-colors ${
                  isItemFocused ? 'text-[#1ed760]' : 'text-white group-hover:text-[#1ed760] group-focus-visible:text-[#1ed760]'
                }`}>
                  {item.title || item.name}
                </h3>
                <p className="text-lg text-[#b3b3b3]">
                  {item.release_date?.substring(0, 4) || item.first_air_date?.substring(0, 4) || 'N/A'}
                </p>
              </Link>
            )
          })
        )}
      </div>
    </div>
  )
}

export function TVInterface() {
  const [focusedRow, setFocusedRow] = useState(0)
  const [focusedItem, setFocusedItem] = useState(0)
  const [focusedNav, setFocusedNav] = useState(0)
  const [navOpen, setNavOpen] = useState(true)
  const [focusedItemPath, setFocusedItemPath] = useState<string | null>(null)
  const containerRef = useRef<HTMLDivElement>(null)
  const navigate = useNavigate()

  const handleKeyDown = useCallback((e: KeyboardEvent) => {
    // D-pad / remote / Arrow keys navigation (full 10ft UX)
    // ponytail: simple switch; handles 'Up' for some remotes; clamps prevent out-of-bounds
    switch (e.key) {
      case 'ArrowUp':
      case 'Up':
        e.preventDefault()
        if (navOpen) {
          setFocusedNav(prev => Math.max(0, prev - 1))
        } else {
          setFocusedRow(prev => Math.max(0, prev - 1))
          setFocusedItem(0)
        }
        break
      case 'ArrowDown':
      case 'Down':
        e.preventDefault()
        if (navOpen) {
          setFocusedNav(prev => Math.min(navItems.length - 1, prev + 1))
        } else {
          setFocusedRow(prev => Math.min(sections.length - 1, prev + 1))
          setFocusedItem(0)
        }
        break
      case 'ArrowLeft':
      case 'Left':
        e.preventDefault()
        if (!navOpen) {
          if (focusedItem === 0) {
            // Real nav parity: left from first item reopens nav (D-pad friendly)
            setNavOpen(true)
          } else {
            setFocusedItem(prev => Math.max(0, prev - 1))
          }
        }
        break
      case 'ArrowRight':
      case 'Right':
        e.preventDefault()
        if (navOpen) {
          setNavOpen(false)
          setFocusedItem(0)
        } else {
          // Real D-pad nav: safe high clamp (per-row ~8); upgrade path: per-section length
          setFocusedItem(prev => Math.min(20, prev + 1))
        }
        break
      case 'Enter':
      case 'Select':
      case ' ': // space also activates (remote/keyboard)
        e.preventDefault()
        if (navOpen) {
          const item = navItems[focusedNav]
          if (item.path) {
            navigate(item.path)
          }
        } else if (focusedItemPath) {
          // Make Enter work reliably (path synced via row useEffect on focus)
          navigate(focusedItemPath)
        }
        break
      case 'Back':
      case 'Escape':
        e.preventDefault()
        if (!navOpen) {
          setNavOpen(true)
        }
        break
      case 'Home':
        e.preventDefault()
        setNavOpen(true)
        setFocusedNav(0)
        break
    }
  }, [focusedRow, focusedItem, focusedNav, navOpen, navigate, focusedItemPath])

  useEffect(() => {
    window.addEventListener('keydown', handleKeyDown)
    return () => window.removeEventListener('keydown', handleKeyDown)
  }, [handleKeyDown])

  // Auto-hide nav after inactivity
  useEffect(() => {
    if (!navOpen) {
      const timer = setTimeout(() => setNavOpen(true), 30000)
      return () => clearTimeout(timer)
    }
  }, [navOpen, focusedRow, focusedItem])

  return (
    <div ref={containerRef} className="min-h-screen bg-[#0a0a0a] text-white overflow-hidden">
      {/* Side Navigation - fixed + animated width, high z to avoid clash with main; full keyboard D-pad support */}
      <motion.div
        className="fixed left-0 top-0 h-full bg-[#121212]/95 backdrop-blur-md z-[60] flex flex-col py-12"
        animate={{ width: navOpen ? 280 : 80 }}
        transition={{ duration: 0.3 }}
        role="complementary"
        aria-label="Sidebar navigation"
      >
        {/* Logo - unified with Header (primary colors, ARIA, Film/Play icon parity) */}
        <div className="px-8 mb-12" role="banner" aria-label="TV Mode Logo">
          <motion.div
            animate={{ justifyContent: navOpen ? 'flex-start' : 'center' }}
            className="focus-visible:ring-2 focus-visible:ring-offset-2 focus-visible:ring-offset-[#121212] focus-visible:ring-[#1ed760] rounded"
          >
            <TVLogo collapsed={!navOpen} />
          </motion.div>
        </div>

        {/* Nav Items - ARIA navigation + focus + aria-current for D-pad state (a11y) */}
        <nav className="flex-1 flex flex-col gap-3 px-4" role="navigation" aria-label="TV Mode Navigation">
          {navItems.map((item, index) => {
            const isFocused = navOpen && focusedNav === index
            return (
              <button
                key={item.id}
                onClick={() => {
                  setFocusedNav(index)
                  if (item.path) navigate(item.path)
                }}
                className={`flex items-center gap-5 px-6 py-5 rounded-2xl transition-all duration-200 focus-visible:ring-2 focus-visible:ring-[#1ed760] outline-none ${
                  isFocused
                    ? 'bg-[#1ed760] text-black scale-105'
                    : 'text-white/70 hover:bg-white/10 hover:text-white'
                }`}
                aria-current={isFocused ? 'page' : undefined}
                aria-label={item.label}
              >
                <span className="flex-shrink-0" aria-hidden="true">{item.icon}</span>
                {navOpen && (
                  <motion.span
                    initial={{ opacity: 0 }}
                    animate={{ opacity: 1 }}
                    className="text-xl font-semibold whitespace-nowrap"
                  >
                    {item.label}
                  </motion.span>
                )}
              </button>
            )
          })}
        </nav>

        {/* User Info */}
        {navOpen && (
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            className="px-8 py-6 border-t border-white/10"
          >
            <div className="flex items-center gap-4">
              <div className="w-12 h-12 bg-[#1f1f1f] rounded-full flex items-center justify-center">
                <span className="text-xl font-bold">U</span>
              </div>
              <div>
                <p className="text-lg font-semibold">User</p>
                <p className="text-sm text-[#b3b3b3]">TV Mode</p>
              </div>
            </div>
          </motion.div>
        )}
      </motion.div>

      {/* Main Content - margin anim accounts for sidebar to avoid layout clash */}
      <motion.div
        className="min-h-screen"
        animate={{ marginLeft: navOpen ? 280 : 80 }}
        transition={{ duration: 0.3 }}
        role="main"
        aria-label="TV discover content"
      >
        {/* Hero Section - uses PosterImage (not raw img/bg) for consistent skeleton/fallback/lazy + no layout shift (ux-design-reviewer) */}
        <div className="relative h-[60vh] bg-gradient-to-b from-[#1a1a2e] to-[#0a0a0a]" role="banner">
          <PosterImage
            src="https://image.tmdb.org/t/p/original/wwemzKWzjKYJFfCniXl0DKJ8f7x.jpg"
            alt=""
            className="absolute inset-0 w-full h-full object-cover opacity-40"
            showFallbackTitle={false}
          />
          {/* stronger multi-layer gradient for text contrast + always-visible affordance (ux-design-reviewer) */}
          <div className="absolute inset-0 bg-gradient-to-t from-[#0a0a0a]/95 via-black/60 to-transparent" aria-hidden="true" />
          <div className="absolute inset-0 bg-gradient-to-b from-black/40 via-transparent to-black/70" aria-hidden="true" />
          <div className="relative h-full flex flex-col justify-end pb-12 px-12">
            <motion.h1
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              className="text-7xl font-bold text-white mb-4 drop-shadow-[0_3px_10px_rgba(0,0,0,0.95)]"
            >
              Discover
            </motion.h1>
            <motion.p
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: 0.1 }}
              className="text-2xl text-[#b3b3b3] drop-shadow-[0_1px_4px_rgba(0,0,0,0.8)]"
            >
              Press D-pad to navigate, Enter to select
            </motion.p>
          </div>
        </div>

        {/* Content Sections */}
        <main className="py-8">
          {sections.map((section, index) => (
            <TVRow
              key={section.endpoint}
              section={section}
              isFocused={!navOpen && focusedRow === index}
              focusedIndex={focusedItem}
              onItemFocus={setFocusedItemPath}
            />
          ))}
        </main>
      </motion.div>

      {/* Focus Indicator - always visible affordance for TV/D-pad mode */}
      {!navOpen && (
        <div className="fixed bottom-8 right-8 bg-[#1ed760] text-black px-6 py-3 rounded-full text-xl font-bold" role="status" aria-live="polite">
          Row {focusedRow + 1} / {sections.length}
        </div>
      )}
    </div>
  )
}
