import { useEffect, useState } from 'react'
import { Link } from 'react-router-dom'
import { Card, CardContent } from '@/components/ui/Card'
import { Input } from '@/components/ui/Input'
import { Button } from '@/components/ui/Button'
import { PosterImage } from '@/components/PosterImage'
import { Heart, Trash2, Film, Compass, Search, RefreshCw, Loader2, Tv2 } from 'lucide-react'
import { useWatchlist, type WatchlistItem } from '@/contexts/WatchlistContext'

interface TVShowResult {
  id: number
  name: string
  first_air_date?: string
  poster_path?: string
  overview?: string
}

export function Watchlist() {
  const { watchlist, isLoading, error, addToWatchlist, updateWatchlistItem, removeFromWatchlist, refreshWatchlist } = useWatchlist()
  const [searchQuery, setSearchQuery] = useState('')
  const [searchResults, setSearchResults] = useState<TVShowResult[]>([])
  const [searching, setSearching] = useState(false)
  const [checking, setChecking] = useState<number | null>(null)

  useEffect(() => {
    refreshWatchlist()
  }, [refreshWatchlist])

  const handleSearch = async () => {
    if (!searchQuery.trim()) return
    setSearching(true)
    try {
      const res = await fetch(`/api/discover/tv/search?q=${encodeURIComponent(searchQuery)}`)
      if (!res.ok) throw new Error('Search failed')
      const data = await res.json()
      setSearchResults(data.results || [])
    } catch (err) {
      console.error(err)
    } finally {
      setSearching(false)
    }
  }

  const handleAddSeries = async (show: TVShowResult) => {
    await addToWatchlist({
      media_type: 'tv_series',
      tmdb_id: show.id,
      title: show.name,
      poster_url: show.poster_path,
    })
    setSearchResults(prev => prev.filter(s => s.id !== show.id))
  }

  const handleCheckNow = async (item: WatchlistItem) => {
    setChecking(item.tmdb_id)
    try {
      await fetch(`/api/watchlist/series/${item.tmdb_id}/check`, { method: 'POST' })
      setTimeout(() => refreshWatchlist(), 2000)
    } finally {
      setChecking(null)
    }
  }

  const movies = watchlist.filter(i => i.media_type === 'movie')
  const series = watchlist.filter(i => i.media_type === 'tv_series' || i.media_type === 'tv_season' || i.media_type === 'tv_episode')

  if (isLoading) {
    return (
      <div className="space-y-6">
        <div>
          <div className="h-9 w-48 bg-muted rounded animate-pulse mb-2" />
          <div className="h-5 w-32 bg-muted rounded animate-pulse" />
        </div>
        <div className="grid gap-4 sm:grid-cols-4 lg:grid-cols-6 xl:grid-cols-8">
          {Array.from({ length: 8 }).map((_, i) => (
            <Card key={i} className="overflow-hidden">
              <div className="aspect-[2/3] bg-muted animate-pulse" />
              <CardContent className="p-3 space-y-2">
                <div className="h-4 bg-muted rounded animate-pulse" />
                <div className="h-3 w-1/2 bg-muted rounded animate-pulse" />
              </CardContent>
            </Card>
          ))}
        </div>
      </div>
    )
  }

  if (error) {
    return (
      <div className="text-center py-12">
        <p className="text-destructive mb-4">{error}</p>
        <button
          onClick={refreshWatchlist}
          className="px-4 py-2 bg-primary text-primary-foreground rounded-md font-medium hover:bg-primary/90"
        >
          Retry
        </button>
      </div>
    )
  }

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-bold tracking-tight">My Watchlist</h1>
          <p className="text-muted-foreground">
            {watchlist.length} {watchlist.length === 1 ? 'item' : 'items'} saved
          </p>
        </div>
      </div>

      <Card>
        <CardContent className="p-4">
          <div className="flex items-center gap-2">
            <Tv2 className="w-5 h-5 text-muted-foreground" />
            <Input
              placeholder="Search for a TV series (e.g. Seinfeld)..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              onKeyDown={(e) => e.key === 'Enter' && handleSearch()}
              className="flex-1"
            />
            <Button onClick={handleSearch} disabled={searching}>
              {searching ? <Loader2 className="w-4 h-4 animate-spin" /> : <Search className="w-4 h-4" />}
              Search
            </Button>
          </div>

          {searchResults.length > 0 && (
            <div className="mt-4 grid gap-2">
              {searchResults.map(show => (
                <div key={show.id} className="flex items-center gap-3 p-2 rounded-lg border hover:bg-accent/50">
                  <PosterImage
                    src={show.poster_path ? `https://image.tmdb.org/t/p/w92${show.poster_path}` : undefined}
                    alt={show.name}
                    title={show.name}
                    className="w-12 h-16 rounded"
                    showFallbackTitle={false}
                  />
                  <div className="flex-1 min-w-0">
                    <p className="font-medium truncate">{show.name}</p>
                    <p className="text-xs text-muted-foreground">{show.first_air_date?.slice(0, 4) || 'Unknown year'}</p>
                  </div>
                  <Button size="sm" onClick={() => handleAddSeries(show)}>
                    Add Series
                  </Button>
                </div>
              ))}
            </div>
          )}
        </CardContent>
      </Card>

      {series.length > 0 && (
        <div>
          <h2 className="text-xl font-semibold mb-3">TV Series</h2>
          <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
            {series.map(item => (
              <Card key={item.id} className="overflow-hidden">
                <div className="flex">
                  <PosterImage
                    src={item.poster_url ? `https://image.tmdb.org/t/p/w500${item.poster_url}` : undefined}
                    alt={item.title}
                    title={item.title}
                    className="w-24 h-36 flex-shrink-0"
                    showFallbackTitle={false}
                  />
                  <CardContent className="p-4 flex-1 min-w-0">
                    <h3 className="font-semibold truncate">{item.title}</h3>
                    <p className="text-sm text-muted-foreground mt-1">
                      {item.missing_count ?? 0} missing
                    </p>
                    <p className="text-xs text-muted-foreground">
                      Last checked: {item.last_checked_at ? new Date(item.last_checked_at).toLocaleString() : 'Never'}
                    </p>
                    <div className="flex items-center gap-2 mt-3">
                      <Button
                        size="sm"
                        variant={item.auto_download ? 'default' : 'outline'}
                        onClick={() => updateWatchlistItem(item.id, { auto_download: !item.auto_download })}
                      >
                        {item.auto_download ? 'Auto-download on' : 'Auto-download off'}
                      </Button>
                      <Button
                        size="sm"
                        variant="outline"
                        onClick={() => handleCheckNow(item)}
                        disabled={checking === item.tmdb_id}
                      >
                        {checking === item.tmdb_id ? <Loader2 className="w-3 h-3 animate-spin" /> : <RefreshCw className="w-3 h-3" />}
                        Check
                      </Button>
                      <Button
                        size="sm"
                        variant="ghost"
                        onClick={() => removeFromWatchlist(item.id)}
                      >
                        <Trash2 className="w-4 h-4 text-destructive" />
                      </Button>
                    </div>
                  </CardContent>
                </div>
              </Card>
            ))}
          </div>
        </div>
      )}

      {movies.length > 0 && (
        <div>
          <h2 className="text-xl font-semibold mb-3">Movies</h2>
          <div className="grid gap-4 sm:grid-cols-4 lg:grid-cols-6 xl:grid-cols-8">
            {movies.map(item => {
              const detailPath = `/movie/${item.tmdb_id}`
              const posterSrc = item.poster_url ? `https://image.tmdb.org/t/p/w500${item.poster_url}` : undefined
              return (
                <Card key={item.id} className="overflow-hidden group relative active:scale-[0.96] transition-transform">
                  <Link to={detailPath}>
                    <div className="aspect-[2/3] relative bg-muted">
                      <PosterImage
                        src={posterSrc}
                        alt={item.title}
                        title={item.title}
                        className="absolute inset-0 w-full h-full object-cover transition-transform duration-300 group-hover:scale-105"
                        showFallbackTitle={false}
                      />
                      <div className="absolute top-2 right-2 px-1.5 py-0.5 bg-black/70 rounded text-[10px] text-white flex items-center">
                        <Film className="w-3 h-3" />
                      </div>
                    </div>
                    <CardContent className="p-3">
                      <h3 className="font-semibold line-clamp-2 text-sm">{item.title}</h3>
                      <p className="text-xs text-muted-foreground mt-1">
                        Added {new Date(item.added_at).toLocaleDateString()}
                      </p>
                    </CardContent>
                  </Link>
                  <button
                    onClick={(e) => {
                      e.preventDefault()
                      e.stopPropagation()
                      removeFromWatchlist(item.id)
                    }}
                    className="absolute top-2 left-2 p-1.5 rounded-full bg-black/70 text-white opacity-0 group-hover:opacity-100 transition-opacity hover:bg-destructive focus:opacity-100"
                    aria-label={`Remove ${item.title} from watchlist`}
                  >
                    <Trash2 className="w-3.5 h-3.5" />
                  </button>
                </Card>
              )
            })}
          </div>
        </div>
      )}

      {watchlist.length === 0 && (
        <Card>
          <CardContent className="p-8 text-center">
            <Heart className="h-12 w-12 mx-auto mb-4 text-muted-foreground/60" />
            <p className="font-medium">Your watchlist is empty</p>
            <p className="text-sm text-muted-foreground mt-1 max-w-xs mx-auto">
              Search for a TV series above or add movies from Discover.
            </p>
            <Link
              to="/discover"
              className="inline-flex items-center gap-2 mt-4 px-4 py-2 bg-primary text-primary-foreground rounded-md font-medium hover:bg-primary/90 transition-colors"
            >
              <Compass className="w-4 h-4" />
              Discover Content
            </Link>
          </CardContent>
        </Card>
      )}
    </div>
  )
}
