import { useState, useEffect, useCallback, useRef } from 'react'
import { useQuery } from '@tanstack/react-query'
import { motion, AnimatePresence } from 'framer-motion'
import { Tv, Grid3X3, Maximize2, RefreshCw, Loader2 } from 'lucide-react'
import { EPGGrid } from '@/components/TVGuide/EPGGrid'
import { ChannelSurf } from '@/components/TVGuide/ChannelSurf'
import type { EPGResponse, EPGChannelResponse, EPGEntry } from '@/types'

type ViewMode = 'grid' | 'surf'

async function fetchEPG(): Promise<EPGResponse> {
  const token = localStorage.getItem('media_manager_token')
  const res = await fetch('/api/channels/epg', {
    headers: token ? { Authorization: `Bearer ${token}` } : undefined,
  })
  if (!res.ok) throw new Error('Failed to fetch EPG')
  return res.json()
}

export function TVGuide() {
  const [viewMode, setViewMode] = useState<ViewMode>('grid')
  const [activeChannel, setActiveChannel] = useState<EPGChannelResponse | null>(null)
  const [activeEntry, setActiveEntry] = useState<EPGEntry | null>(null)
  const refreshIntervalRef = useRef<ReturnType<typeof setInterval>>()

  const { data: epg, isLoading, isError, refetch } = useQuery({
    queryKey: ['epg'],
    queryFn: fetchEPG,
    refetchInterval: 60_000, // refresh every minute for accurate now/next
  })

  // Auto-refresh EPG data every 60s
  useEffect(() => {
    refreshIntervalRef.current = setInterval(() => refetch(), 60_000)
    return () => clearInterval(refreshIntervalRef.current)
  }, [refetch])

  const handleSelectProgram = useCallback((entry: EPGEntry, channel: EPGChannelResponse) => {
    setActiveChannel(channel)
    setActiveEntry(entry)
    setViewMode('surf')
  }, [])

  const handleSwitchChannel = useCallback((channel: EPGChannelResponse, entry: EPGEntry) => {
    setActiveChannel(channel)
    setActiveEntry(entry)
  }, [])

  const handleBackToGrid = useCallback(() => {
    setViewMode('grid')
  }, [])

  // Loading state
  if (isLoading) {
    return (
      <div className="min-h-screen bg-[#0a0a0a] flex items-center justify-center">
        <div className="text-center">
          <Loader2 className="w-12 h-12 text-[#1ed760] animate-spin mx-auto mb-4" />
          <p className="text-white/60 text-lg">Loading TV Guide...</p>
        </div>
      </div>
    )
  }

  // Error state
  if (isError || !epg) {
    return (
      <div className="min-h-screen bg-[#0a0a0a] flex items-center justify-center">
        <div className="text-center">
          <Tv className="w-16 h-16 text-white/20 mx-auto mb-4" />
          <p className="text-white/60 text-xl mb-2">Unable to load TV Guide</p>
          <p className="text-white/40 mb-6">Make sure the backend service is running</p>
          <button
            onClick={() => refetch()}
            className="px-6 py-2 bg-[#1ed760] text-black font-semibold rounded-full hover:bg-[#1ed760]/90 transition-colors"
          >
            Retry
          </button>
        </div>
      </div>
    )
  }

  return (
    <div className="min-h-screen bg-[#0a0a0a] text-white flex flex-col">
      {/* Header */}
      <header className="flex items-center justify-between px-6 py-4 bg-[#121212] border-b border-white/10">
        <div className="flex items-center gap-3">
          <Tv className="w-6 h-6 text-[#1ed760]" />
          <h1 className="text-xl font-bold">TV Guide</h1>
          <span className="text-white/40 text-sm">
            {epg.channels.length} channels
          </span>
        </div>
        <div className="flex items-center gap-2">
          {viewMode === 'surf' && (
            <span className="text-white/40 text-sm mr-2">
              {activeChannel?.channel.name} &middot; CH {epg.channels.findIndex(c => c.channel.id === activeChannel?.channel.id) + 1}
            </span>
          )}
          <button
            onClick={() => refetch()}
            className="p-2 text-white/60 hover:text-white hover:bg-white/10 rounded-lg transition-colors"
            title="Refresh"
          >
            <RefreshCw className="w-5 h-5" />
          </button>
          <button
            onClick={() => setViewMode(viewMode === 'grid' ? 'surf' : 'grid')}
            className={`p-2 rounded-lg transition-colors ${
              viewMode === 'surf'
                ? 'bg-[#1ed760]/20 text-[#1ed760]'
                : 'text-white/60 hover:text-white hover:bg-white/10'
            }`}
            title={viewMode === 'grid' ? 'Enter Surf Mode' : 'Show Guide'}
          >
            {viewMode === 'grid' ? <Maximize2 className="w-5 h-5" /> : <Grid3X3 className="w-5 h-5" />}
          </button>
        </div>
      </header>

      {/* Content */}
      <div className="flex-1 relative">
        <AnimatePresence mode="wait">
          {viewMode === 'grid' ? (
            <motion.div
              key="grid"
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0 }}
              className="h-full"
            >
              <EPGGrid epg={epg} onSelectProgram={handleSelectProgram} />
            </motion.div>
          ) : activeChannel && activeEntry ? (
            <motion.div
              key="surf"
              initial={{ opacity: 0, scale: 0.95 }}
              animate={{ opacity: 1, scale: 1 }}
              exit={{ opacity: 0, scale: 0.95 }}
              className="absolute inset-0"
            >
              <ChannelSurf
                channel={activeChannel}
                entry={activeEntry}
                allChannels={epg.channels}
                onSwitchChannel={handleSwitchChannel}
                onBackToGrid={handleBackToGrid}
              />
            </motion.div>
          ) : null}
        </AnimatePresence>
      </div>
    </div>
  )
}
