import { useState, useEffect, useRef, useCallback } from 'react'
import { Loader2, Film } from 'lucide-react'

interface PosterImageProps {
  src?: string
  alt: string
  title?: string
  className?: string
  onLoad?: () => void
  // When used with separate metadata below the card, set false to avoid duplicate titles in fallback
  showFallbackTitle?: boolean
}

export function PosterImage({ src, alt, title, className = '', onLoad, showFallbackTitle = true }: PosterImageProps) {
  const [isVisible, setIsVisible] = useState(false)
  const [isLoaded, setIsLoaded] = useState(false)
  const [imageSrc, setImageSrc] = useState<string | undefined>(src)
  const [isFetching, setIsFetching] = useState(false)
  const [fetchFailed, setFetchFailed] = useState(false)
  const imgRef = useRef<HTMLDivElement>(null)
  const hasAttemptedFetch = useRef(false)

  // Intersection Observer for lazy loading
  useEffect(() => {
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setIsVisible(true)
          observer.disconnect()
        }
      },
      {
        rootMargin: '200px', // Start loading 200px before visible
        threshold: 0.01,
      }
    )

    if (imgRef.current) {
      observer.observe(imgRef.current)
    }

    return () => observer.disconnect()
  }, [])

  // Fetch poster from backend if not provided
  const fetchPoster = useCallback(async () => {
    if (!title || hasAttemptedFetch.current) return
    
    hasAttemptedFetch.current = true
    setIsFetching(true)
    
    try {
      const response = await fetch(`/api/library/poster-by-title?title=${encodeURIComponent(title)}`)
      if (response.ok) {
        const data = await response.json()
        if (data.poster_url) {
          setImageSrc(data.poster_url)
          setFetchFailed(false)
        } else {
          setFetchFailed(true)
        }
      } else {
        setFetchFailed(true)
      }
    } catch (error) {
      console.error('Failed to fetch poster:', error)
      setFetchFailed(true)
    } finally {
      setIsFetching(false)
    }
  }, [title])

  // Trigger fetch when visible
  useEffect(() => {
    if (isVisible && !imageSrc && title && !hasAttemptedFetch.current) {
      fetchPoster()
    }
  }, [isVisible, imageSrc, title, fetchPoster])

  const handleImageLoad = () => {
    setIsLoaded(true)
    onLoad?.()
  }

  const handleImageError = () => {
    setFetchFailed(true)
    setIsLoaded(false)
  }

  // Update src if prop changes
  useEffect(() => {
    if (src && src !== imageSrc) {
      setImageSrc(src)
      setIsLoaded(false)
      setFetchFailed(false)
    }
  }, [src])

  // Fixed fallback logic: show fallback immediately on fail or no src after visibility (prevents blank images)
  const hasSrc = !!imageSrc
  const showSkeleton = isVisible && !isLoaded && hasSrc && !fetchFailed
  const showFallback = !hasSrc || fetchFailed

  return (
    <div ref={imgRef} className={`relative ${className}`} role="img" aria-label={alt || title || 'Media poster'}>
      {/* Skeleton placeholder */}
      {(showSkeleton || (isVisible && !hasSrc && !fetchFailed)) && (
        <div className="absolute inset-0 bg-muted animate-pulse">
          {isFetching && (
            <div className="absolute inset-0 flex items-center justify-center">
              <Loader2 className="h-6 w-6 text-muted-foreground animate-spin" />
            </div>
          )}
        </div>
      )}
      
      {/* Text fallback when no poster available - always renders visible fallback to avoid blanks */}
      {showFallback && (
        <div className="absolute inset-0 flex flex-col items-center justify-center bg-muted dark:bg-slate-800 text-foreground p-4 border-2 border-dashed border-border" aria-hidden={!showFallbackTitle}>
          <Film className="h-14 w-14 mb-2" aria-hidden="true" />
          {showFallbackTitle && (
            <p className="text-xs text-center line-clamp-3 leading-relaxed font-medium">
              {alt || title || 'No poster'}
            </p>
          )}
        </div>
      )}
      
      {/* Actual image - loads only when visible with src */}
      {isVisible && hasSrc && !fetchFailed && (
        <img
          src={imageSrc}
          alt={alt}
          className={`absolute inset-0 w-full h-full object-cover transition-opacity duration-500 outline outline-1 outline-black/10 dark:outline-white/10 ${
            isLoaded ? 'opacity-100' : 'opacity-0'
          }`}
          onLoad={handleImageLoad}
          onError={handleImageError}
          loading="lazy"
        />
      )}
    </div>
  )
}
