import { useEffect, useRef } from 'react'
import { useParams, useSearchParams, Link } from 'react-router-dom'
import { useInfiniteQuery } from '@tanstack/react-query'
import { motion } from 'framer-motion'
import { Star, Film, ArrowLeft } from 'lucide-react'

interface DiscoverItem {
  id: number
  title?: string
  name?: string
  poster_path: string
  backdrop_path: string
  overview: string
  release_date?: string
  first_air_date?: string
  vote_average: number
  vote_count: number
  media_type: string
  genre_ids?: number[]
  adult?: boolean
  popularity?: number
}

const ADULT_TERMS = /porn|xxx|adult|onlyfans|brazzers|naughtyamerica|manyvids|fansly/i

function isAdultContent(item: DiscoverItem): boolean {
  if (item.adult) return true
  const title = (item.title || item.name || '').toLowerCase()
  return ADULT_TERMS.test(title)
}

const categoryTitles: Record<string, Record<string, string>> = {
  movie: {
    trending: 'Trending Movies',
    popular: 'Popular Movies',
    now_playing: 'Now Playing',
    upcoming: 'Upcoming Movies',
    top_rated: 'Top Rated Movies',
    hidden_gems: 'Under the Radar',
  },
  tv: {
    trending: 'Trending TV Shows',
    popular: 'Popular TV Shows',
    on_the_air: 'On The Air',
    airing_today: 'Airing Today',
    top_rated: 'Top Rated TV',
    hidden_gems: 'Under the Radar TV',
  },
}

export function DiscoverSection() {
  const { type, category } = useParams<{ type: string; category: string }>()
  const [searchParams] = useSearchParams()
  const sentinelRef = useRef<HTMLDivElement>(null)

  const mediaType = type === 'tv' ? 'tv' : 'movie'
  const slug = category || 'trending'

  const title = categoryTitles[mediaType]?.[slug] || 'Discover'

  const { data, isLoading, fetchNextPage, hasNextPage, isFetchingNextPage, error } = useInfiniteQuery<DiscoverItem[], Error>({
    queryKey: ['discover-section', mediaType, slug, searchParams.toString()],
    initialPageParam: 1,
    queryFn: async ({ pageParam }) => {
      const endpoint =
        slug === 'hidden_gems'
          ? `/api/discover/hidden_gems?type=${mediaType}`
          : `/api/discover/category?type=${mediaType}&category=${encodeURIComponent(slug)}`
      const url = new URL(endpoint, window.location.origin)
      url.searchParams.set('page', String(pageParam))
      searchParams.forEach((value, key) => {
        if (key !== 'page') url.searchParams.set(key, value)
      })
      const res = await fetch(url.toString())
      if (!res.ok) throw new Error('Failed to fetch category')
      const json = await res.json()
      return json.results || []
    },
    staleTime: 5 * 60 * 1000,
    getNextPageParam: (_lastPage, allPages) => {
      if (allPages.length >= 10) return undefined
      return allPages.length + 1
    },
  })

  useEffect(() => {
    const el = sentinelRef.current
    if (!el) return
    const observer = new IntersectionObserver(
      (entries) => {
        if (entries[0].isIntersecting && hasNextPage && !isFetchingNextPage) {
          fetchNextPage()
        }
      },
      { rootMargin: '400px' }
    )
    observer.observe(el)
    return () => observer.disconnect()
  }, [hasNextPage, isFetchingNextPage, fetchNextPage])

  const items: DiscoverItem[] = []
  const seen = new Set<number>()
  data?.pages.forEach((page) => {
    page.forEach((item) => {
      if (isAdultContent(item)) return
      if (seen.has(item.id)) return
      seen.add(item.id)
      items.push(item)
    })
  })

  return (
    <div className="min-h-screen bg-background px-4 sm:px-6 lg:px-8 py-6">
      <div className="flex items-center gap-3 mb-6">
        <Link
          to="/discover"
          className="flex items-center justify-center h-9 w-9 rounded-full bg-muted hover:bg-accent text-foreground transition"
          aria-label="Back to discover"
        >
          <ArrowLeft className="w-5 h-5" aria-hidden="true" />
        </Link>
        <motion.h1
          initial={{ opacity: 0, y: 10 }}
          animate={{ opacity: 1, y: 0 }}
          className="text-2xl sm:text-3xl font-bold text-foreground"
        >
          {title}
        </motion.h1>
      </div>

      {error && (
        <div className="rounded-lg border border-destructive/50 bg-destructive/10 p-4 text-destructive mb-6">
          {error.message}
        </div>
      )}

      {isLoading && (
        <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 xl:grid-cols-6 gap-4">
          {Array.from({ length: 18 }).map((_, i) => (
            <div key={i} className="flex flex-col">
              <div className="aspect-[2/3] bg-muted rounded-lg animate-pulse" />
              <div className="h-4 w-3/4 bg-muted rounded mt-2 animate-pulse" />
            </div>
          ))}
        </div>
      )}

      {!isLoading && items.length === 0 && (
        <p className="text-muted-foreground">No titles found for this category.</p>
      )}

      <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 xl:grid-cols-6 gap-4">
        {items.map((item) => {
          const isTV = item.media_type === 'tv' || mediaType === 'tv'
          return (
            <Link
              key={item.id}
              to={`/${isTV ? 'tv' : 'movie'}/${item.id}`}
              className="group/card cursor-pointer focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring rounded-lg active:scale-[0.96] transition-transform"
              aria-label={`${item.title || item.name} (${item.release_date?.substring(0, 4) || item.first_air_date?.substring(0, 4) || 'N/A'}) ${isTV ? 'TV' : 'movie'}, rated ${item.vote_average.toFixed(1)}`}
            >
              <div className={`relative aspect-[2/3] rounded-lg overflow-hidden bg-muted transition-all duration-200 shadow-md group-hover/card:shadow-xl group-hover/card:-translate-y-0.5 ${isTV ? 'ring-1 ring-violet-500/40' : 'ring-1 ring-border'}`}>
                {item.poster_path ? (
                  <img
                    src={`https://image.tmdb.org/t/p/w500${item.poster_path}`}
                    alt={item.title || item.name}
                    className="w-full h-full object-cover transition-transform duration-300 group-hover/card:scale-105 outline outline-1 outline-black/10 dark:outline-white/10"
                    loading="lazy"
                    onError={(e) => {
                      const target = e.currentTarget
                      target.style.display = 'none'
                      const fallback = target.nextElementSibling as HTMLElement | null
                      if (fallback) fallback.style.display = 'flex'
                    }}
                  />
                ) : null}
                <div
                  className={`w-full h-full flex-col items-center justify-center bg-muted text-foreground p-2 border-2 border-dashed border-border ${item.poster_path ? 'hidden' : 'flex'}`}
                  aria-hidden={!!item.poster_path}
                >
                  <Film className="w-14 h-14 mb-2" aria-hidden="true" />
                  <p className="text-[10px] text-center line-clamp-3 leading-relaxed font-medium">{item.title || item.name || 'No poster'}</p>
                </div>
                {isTV && (
                  <div className="absolute top-2 left-2 px-1.5 py-px text-[9px] font-semibold tracking-[1px] bg-violet-600/90 text-white rounded" aria-hidden="true">TV</div>
                )}
                {!isTV && (
                  <div className="absolute top-2 left-2 px-1.5 py-px text-[9px] font-semibold tracking-[1px] bg-emerald-600/80 text-white rounded" aria-hidden="true">MOVIE</div>
                )}
                <div className="absolute bottom-2 right-2 flex items-center gap-0.5 rounded bg-background/80 px-1.5 py-0.5 text-yellow-400 border border-border/30" aria-hidden="true">
                  <Star className="w-3 h-3 fill-current" />
                  <span className="text-[11px] font-semibold tabular-nums">{item.vote_average.toFixed(1)}</span>
                </div>
                <div className="absolute inset-0 bg-gradient-to-t from-black/70 via-transparent to-transparent opacity-0 group-hover/card:opacity-100 transition-opacity duration-300" aria-hidden="true" />
              </div>
              <h3 className="mt-2 text-sm font-semibold text-foreground line-clamp-2 group-hover/card:text-emerald-500 transition-colors">
                {item.title || item.name}
              </h3>
              <p className="text-xs text-muted-foreground" aria-hidden="true">
                {item.release_date?.substring(0, 4) || item.first_air_date?.substring(0, 4) || 'N/A'}
              </p>
            </Link>
          )
        })}
      </div>

      <div ref={sentinelRef} className="h-8 mt-6 flex items-center justify-center">
        {isFetchingNextPage && (
          <div className="w-8 h-8 border-2 border-emerald-500 border-t-transparent rounded-full animate-spin" aria-label="Loading more" />
        )}
      </div>
    </div>
  )
}
