import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/components/ui/Card'
import { useStats, useLibrary } from '@/hooks/useApi'
import { Download, Library, Search, CheckCircle, XCircle, Clock, Activity, ArrowRight } from 'lucide-react'
import { Link } from 'react-router-dom'
import { PosterImage } from '@/components/PosterImage'

// Enhanced stat cards with improved visual weight and contrast
const statCards = [
  { name: 'Pending', key: 'pending' as const, icon: Clock, color: 'text-yellow-500' },
  { name: 'Downloading', key: 'downloading' as const, icon: Activity, color: 'text-blue-500' },
  { name: 'Completed', key: 'completed' as const, icon: CheckCircle, color: 'text-green-500' },
  { name: 'Failed', key: 'failed' as const, icon: XCircle, color: 'text-red-500' },
]

export function Dashboard() {
  const { data: stats, isLoading: statsLoading } = useStats()
  const { data: movies, isLoading: libraryLoading } = useLibrary()

  const downloadStats = stats?.downloads || { pending: 0, downloading: 0, completed: 0, failed: 0 }
  const pending = downloadStats.pending
  const downloading = downloadStats.downloading
  const completed = downloadStats.completed
  const failed = downloadStats.failed
  const totalActivity = pending + downloading + completed + failed

  const recentMedia = movies?.slice(0, 6) || []
  const hasRecent = recentMedia.length > 0
  // Show rich empty onboarding ONLY when truly nothing (no activity + no library) to avoid empty space
  const showRichEmptyState = !statsLoading && !libraryLoading && totalActivity === 0 && !hasRecent

  return (
    <div className="space-y-6">
      <div>
        <h1 className="text-3xl font-bold tracking-tight">Dashboard</h1>
        <p className="text-muted-foreground">
          Welcome to your media manager. Monitor your downloads and library.
        </p>
      </div>

      {/* Stats Grid - improved cards: tighter padding, stronger hover, weight/contrast */}
      <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-4">
        {statCards.map((stat) => {
          const value = downloadStats[stat.key]
          const StatIcon = stat.icon
          return (
            <Card key={stat.name} className="border bg-card shadow-sm hover:shadow-lg hover:-translate-y-px transition-all" role="group" aria-label={`${stat.name} count`}>
              <CardHeader className="flex flex-row items-center justify-between space-y-0 p-4 pb-2">
                <CardTitle className="text-sm font-medium">{stat.name}</CardTitle>
                <StatIcon className={`h-4 w-4 ${stat.color}`} aria-hidden="true" />
              </CardHeader>
              <CardContent className="p-4 pt-1">
                <div className="text-3xl font-semibold tabular-nums text-foreground" aria-live="polite">
                  {statsLoading ? '...' : value}
                </div>
              </CardContent>
            </Card>
          )
        })}
      </div>

      {/* Rich empty state (zero activity + zero library) - provides visual onboarding without leaving empty space */}
      {showRichEmptyState && (
        <Card className="border-2 border-dashed">
          <CardContent className="p-8">
            <div className="text-center mb-6">
              <h3 className="text-xl font-semibold mb-2">Get started with Media Manager</h3>
              <p className="text-muted-foreground max-w-md mx-auto">
                No downloads or library items yet. Start by searching for content, managing downloads, or building your library.
              </p>
            </div>

            {/* Onboarding CTAs - improved with hover lift for card feel */}
            <div className="grid gap-3 sm:grid-cols-3 mb-2">
              <Link to="/search" className="block">
                <Card className="h-full hover:bg-accent/60 hover:shadow-sm transition-all cursor-pointer group active:scale-[0.96]">
                  <CardContent className="p-4 flex items-center justify-between">
                    <div>
                      <div className="font-medium flex items-center gap-2"><Search className="h-4 w-4" /> Search &amp; Discover</div>
                      <p className="text-xs text-muted-foreground mt-1">Find torrents and approve downloads</p>
                    </div>
                    <ArrowRight className="h-4 w-4 text-muted-foreground group-hover:translate-x-0.5 transition" />
                  </CardContent>
                </Card>
              </Link>
              <Link to="/downloads" className="block">
                <Card className="h-full hover:bg-accent/60 hover:shadow-sm transition-all cursor-pointer group active:scale-[0.96]">
                  <CardContent className="p-4 flex items-center justify-between">
                    <div>
                      <div className="font-medium flex items-center gap-2"><Download className="h-4 w-4" /> View Downloads</div>
                      <p className="text-xs text-muted-foreground mt-1">Monitor queue and progress</p>
                    </div>
                    <ArrowRight className="h-4 w-4 text-muted-foreground group-hover:translate-x-0.5 transition" />
                  </CardContent>
                </Card>
              </Link>
              <Link to="/library" className="block">
                <Card className="h-full hover:bg-accent/60 hover:shadow-sm transition-all cursor-pointer group active:scale-[0.96]">
                  <CardContent className="p-4 flex items-center justify-between">
                    <div>
                      <div className="font-medium flex items-center gap-2"><Library className="h-4 w-4" /> Browse Library</div>
                      <p className="text-xs text-muted-foreground mt-1">Organize your collection</p>
                    </div>
                    <ArrowRight className="h-4 w-4 text-muted-foreground group-hover:translate-x-0.5 transition" />
                  </CardContent>
                </Card>
              </Link>
            </div>
          </CardContent>
        </Card>
      )}

      {/* Rich recent media visuals using PosterImage - always shown when available to fill space and provide value */}
      {hasRecent && (
        <div className="space-y-3">
          <div className="flex items-center justify-between">
            <h3 className="text-sm font-medium tracking-tight">Recent Library</h3>
            <Link to="/library" className="text-sm text-primary flex items-center gap-1 hover:underline">
              View all <ArrowRight className="h-3 w-3" />
            </Link>
          </div>
          <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-6 gap-4">
            {recentMedia.map((item) => (
              <Link key={item.path} to="/library" className="group block">
                <Card className="overflow-hidden h-full transition-all hover:shadow-md hover:-translate-y-0.5 active:scale-[0.96]">
                  <div className="aspect-[2/3] relative bg-muted">
                    <PosterImage
                      src={item.poster_url}
                      alt={item.title}
                      title={item.title}
                      className="absolute inset-0 w-full h-full object-cover"
                      showFallbackTitle={false}
                    />
                  </div>
                  <CardContent className="p-3">
                    <p className="text-sm font-medium line-clamp-2 group-hover:text-primary transition-colors">{item.title}</p>
                    {item.size && (
                      <p className="text-[10px] text-muted-foreground mt-0.5 truncate">{item.size}</p>
                    )}
                  </CardContent>
                </Card>
              </Link>
            ))}
          </div>
        </div>
      )}

      {/* Quick Actions - improved cards with tighter padding, consistent hover, no wasted inner space, better weight */}
      <div className="grid gap-4 md:grid-cols-3" role="navigation" aria-label="Quick actions">
        <Link to="/downloads" className="block">
          <Card className="cursor-pointer hover:bg-accent hover:border-accent hover:shadow-lg transition-all h-full border bg-card shadow-sm">
            <CardHeader className="p-4">
              <CardTitle className="flex items-center gap-2 text-base">
                <Download className="h-5 w-5" aria-hidden="true" />
                Downloads
              </CardTitle>
              <CardDescription>Manage your download queue</CardDescription>
            </CardHeader>
            <CardContent className="p-4 pt-0">
              <p className="text-sm text-muted-foreground">
                View active downloads, cancel or restart tasks, and monitor progress.
              </p>
            </CardContent>
          </Card>
        </Link>

        <Link to="/library" className="block">
          <Card className="cursor-pointer hover:bg-accent hover:border-accent hover:shadow-lg transition-all h-full border bg-card shadow-sm">
            <CardHeader className="p-4">
              <CardTitle className="flex items-center gap-2 text-base">
                <Library className="h-5 w-5" aria-hidden="true" />
                Library
              </CardTitle>
              <CardDescription>Browse your media collection</CardDescription>
            </CardHeader>
            <CardContent className="p-4 pt-0">
              <p className="text-sm text-muted-foreground">
                View downloaded movies, fetch posters, and organize your library.
              </p>
            </CardContent>
          </Card>
        </Link>

        <Link to="/search" className="block">
          <Card className="cursor-pointer hover:bg-accent hover:border-accent hover:shadow-lg transition-all h-full border bg-card shadow-sm">
            <CardHeader className="p-4">
              <CardTitle className="flex items-center gap-2 text-base">
                <Search className="h-5 w-5" aria-hidden="true" />
                Search
              </CardTitle>
              <CardDescription>Find new content</CardDescription>
            </CardHeader>
            <CardContent className="p-4 pt-0">
              <p className="text-sm text-muted-foreground">
                Search across multiple indexers and approve downloads.
              </p>
            </CardContent>
          </Card>
        </Link>
      </div>
    </div>
  )
}